read_stock_and_suppliers.source:
async function run(input, tools) {
  const settings = (input && input.settings) || {};
  const rules = (input && input.rules) || {};
  const maxDays = Number(rules.max_delivery_days ?? settings.max_delivery_days);
  const orders_to_place = [];

  let stockRows = [], supplierRows = [];
  try {
    const s = await tools.sheets.read({ sheet: settings.stock_sheet });
    stockRows = (s && Array.isArray(s.rows)) ? s.rows : [];
  } catch (e) { stockRows = []; }
  try {
    const p = await tools.sheets.read({ sheet: settings.suppliers_sheet });
    supplierRows = (p && Array.isArray(p.rows)) ? p.rows : [];
  } catch (e) { supplierRows = []; }

  const low = [];
  for (const row of stockRows) {
    if (!row) continue;
    const fabric = row.fabric;
    const metres = Number(row.metres);
    const minimum = Number(row.minimum);
    if (!fabric || !isFinite(metres) || !isFinite(minimum)) continue;
    if (metres < minimum) low.push({ fabric: String(fabric), metres, minimum });
  }

  for (const item of low) {
    const need = item.minimum - item.metres;
    if (!(need > 0)) continue;
    let best = null;
    for (const row of supplierRows) {
      if (!row) continue;
      if (String(row.fabric) !== item.fabric) continue;
      const price = Number(row.price_usdc);
      const days = Number(row.delivery_days);
      if (!isFinite(price) || !isFinite(days)) continue;
      if (isFinite(maxDays) && days > maxDays) continue;
      if (!best || price < best.price) {
        best = { supplier: String(row.supplier ?? ""), price };
      }
    }
    if (!best) continue;
    orders_to_place.push({
      fabric: item.fabric,
      supplier: best.supplier,
      metres_to_order: need,
      total_cost_usdc: Math.round(need * best.price * 100) / 100
    });
  }

  return { orders_to_place };
}

prepare_write_orders.source:
async function run(input, tools) {
  const settings = input.settings || {};
  const orders = input.orders_to_place;
  const rows = Array.isArray(orders) ? orders : [];
  return {
    write_orders_arg: {
      sheet: settings.orders_sheet,
      rows: rows
    }
  };
}

